//! Analog-model EQ designers of the passive and vintage EQs.
//!
//! GENERATED from Universal Control's `dspusbdevice.dll` by lifting the x64 SSE code of each
//! designer statement by statement (single-precision, same operation order), then checked against
//! the original running in an emulator (see `docs/uc-dll-notes.md`). Do not edit by hand.
//!
//! | function | UC address | output |
//! |---|---|---|
//! | `passive_high` | 0x18001b3a0 | `Lfdf`, 7 coefficients (3rd order) |
//! | `passive_low` | 0x18001bb40 | `Bqdf` band 1 |
//! | `vintage_low` | 0x18001e200 | `Lfdf` (analog path, fs <= 176.4 kHz) |
//! | `vintage_high` | 0x18001dcc0 | `Bqdf` band 1 |
//! | `vintage_lomid` | 0x18001d9b0 | `Bqdf` band 2 |
//! | `vintage_himid` | 0x18001d6a0 | `Bqdf` band 3 |
//!
//! `t` is the sample period (1 / fs). Outputs are `[b0, -a1, b1, -a2, b2(, -a3, b3)]`.

#![allow(
    clippy::excessive_precision,
    clippy::approx_constant,
    clippy::unreadable_literal
)]

pub type Coefs5 = [f32; 5];
pub type Coefs7 = [f32; 7];

/// UC 0x18001bea0: normalize by a0 and apply an output gain to the numerator.
fn norm2(a: [f32; 3], b: [f32; 3], g: f32) -> Coefs5 {
    let i = 1.0 / a[0];
    [
        b[0] * i * g,
        -(a[1] * i),
        b[1] * i * g,
        -(a[2] * i),
        b[2] * i * g,
    ]
}

fn norm3(a: [f32; 4], b: [f32; 4], g: f32) -> Coefs7 {
    let i = 1.0 / a[0];
    [
        b[0] * i * g,
        -(a[1] * i),
        b[1] * i * g,
        -(a[2] * i),
        b[2] * i * g,
        -(a[3] * i),
        b[3] * i * g,
    ]
}

